"""SBT-003 deterministic freeze-candidate generator. Hidden from evaluated models."""
from pathlib import Path
import json,hashlib
import numpy as np,pandas as pd
SEED=20260918;N=2400;ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'synthetic_data';OUT.mkdir(exist_ok=True);rng=np.random.default_rng(SEED)
tenure=rng.choice(['<1y','1-2y','3-5y','6+y'],N,p=[.16,.24,.31,.29]);plan=rng.choice(['Essential','Standard','Premium'],N,p=[.30,.50,.20]);legacy=rng.binomial(1,np.select([tenure=='<1y',tenure=='1-2y',tenure=='3-5y',tenure=='6+y'],[.04,.10,.28,.52]));latent=rng.normal(0,1,N)-.48*legacy
outage=rng.binomial(1,1/(1+np.exp(-(-1.15+.75*legacy+.15*(plan=='Premium')))));contact=rng.binomial(1,1/(1+np.exp(-(-1.35+1.05*outage+.55*legacy+.25*(plan=='Premium')))));rp=1/(1+np.exp(-(.65-.85*legacy-.55*outage+.18*latent)));resolved=np.where(contact==1,rng.binomial(1,rp),np.nan);unresolved=((contact==1)&(np.nan_to_num(resolved)==0)).astype(int);experience=latent-1.05*unresolved-.48*outage+rng.normal(0,.55,N)
def lk(x):return np.digitize(x,(-1.25,-.45,.25,1.05))+1
reliability=lk(experience+.2+rng.normal(0,.45,N));value=lk(.55*experience+rng.normal(0,.75,N));ease=lk(.58*experience+rng.normal(0,.70,N));trust=lk(.82*experience+rng.normal(0,.52,N));sat=lk(.90*experience+rng.normal(0,.48,N));renew=lk(.72*experience+rng.normal(0,.68,N));support=np.where(contact==1,lk(.75*experience+.65*np.nan_to_num(resolved)+rng.normal(0,.65,N)),np.nan);nps=np.clip(np.rint(5.9+1.55*experience+rng.normal(0,1.65,N)),0,10).astype(int)
wt=np.select([plan=='Essential',plan=='Standard',plan=='Premium'],[1.08,1.03,.72])*np.where(contact==1,.82,1.07)*rng.lognormal(0,.06,N);wt/=wt.mean()
df=pd.DataFrame({'respondent_id':[f'SBT003_{i+1:04d}' for i in range(N)],'tenure_band':tenure,'plan_tier':plan,'legacy_plan':legacy,'nps_0_10':nps,'overall_satisfaction_5':sat,'renewal_intent_5':renew,'reliability_5':reliability,'value_5':value,'ease_5':ease,'trust_5':trust,'outage_90d':outage,'support_contact_90d':contact,'support_quality_5':support,'resolved_first_contact':resolved,'wt_final':wt});df.to_csv(OUT/'respondents.csv',index=False);p=OUT/'respondents.csv';audit={'version':'0.1-freeze-candidate','seed':SEED,'n':N,'premium_unresolved_n':int(((plan=='Premium')&(contact==1)&(np.nan_to_num(resolved)==0)).sum()),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()};(OUT/'generation_audit.json').write_text(json.dumps(audit,indent=2))
